import {setupPhotonTools} from './photon-tools.js';
import {clockRate,tidalGradient,tracePhoton,CRITICAL_IMPACT,blackholeReference} from './blackhole-math.js';
const $=s=>document.querySelector(s);
export function setupRelativityLab(api,getMass){
 const root=$('#relativity-lab');root.innerHTML=`
 <div class="relativity-heading"><div><span class="eyebrow">THE RELATIVITY LAB / THREE WAYS TO BREAK YOUR INTUITION</span><h2>Stay curious.<br><em>Get dangerously close.</em></h2></div><p>These are controls, not just a view.<br>Change one thing. Watch the universe respond.</p></div>
 <div class="relativity-tabs" role="tablist" aria-label="Relativity experiments"><button id="tab-photon" role="tab" aria-selected="true" aria-controls="panel-photon" data-relativity="photon">01 <strong>Chase a photon</strong><span>Light & capture</span></button><button id="tab-clock" role="tab" aria-selected="false" aria-controls="panel-clock" tabindex="-1" data-relativity="clock">02 <strong>Borrow some time</strong><span>Gravity & clocks</span></button><button id="tab-tides" role="tab" aria-selected="false" aria-controls="panel-tides" tabindex="-1" data-relativity="tides">03 <strong>Feel the stretch</strong><span>Mass & tidal forces</span></button></div>
 <div id="panel-photon" role="tabpanel" aria-labelledby="tab-photon" class="relativity-panel"><div class="experiment-visual"><canvas id="photon-canvas" role="img" aria-label="Calculated planar light trajectory near a black hole. Change impact parameter to compare capture and escape."></canvas><div class="experiment-badge"><i></i> NULL GEODESIC / NONROTATING REFERENCE</div><span class="experiment-hint">DRAG VERTICALLY TO AIM YOUR PHOTON</span></div><div class="experiment-console"><span class="eyebrow">EXPERIMENT / 01</span><h3>A little closer.<br>A different destiny.</h3><p>A tiny change in the incoming path can decide whether light escapes or disappears beyond the horizon.</p><label>Impact parameter / b <output id="photon-impact-label"></output><input id="photon-impact" type="range" min="1.5" max="5.5" step=".001" value="2.65"></label><div class="experiment-presets"><button data-impact="2.4">Captured</button><button data-impact="2.600">Near the edge</button><button data-impact="3.4">Escapes</button></div><div class="experiment-result" aria-live="polite"><span>PHOTON FATE</span><strong id="photon-outcome"></strong><small id="photon-detail"></small></div><button class="primary" id="photon-replay">Launch photon <span>↗</span></button><label class="experiment-check"><input id="photon-bundle" type="checkbox"> Compare nearby rays</label><p class="experiment-note">A planar Schwarzschild null trajectory, integrated with RK4 in horizon units. Critical impact parameter at infinity: 3√3/2 ≈ 2.598 Rs. Numerical paths near this boundary are resolution limited; no finite numerical trace is claimed to orbit forever.</p></div></div>
 <div id="panel-clock" role="tabpanel" aria-labelledby="tab-clock" class="relativity-panel" hidden><div class="experiment-visual"><canvas id="clock-canvas" role="img" aria-label="Two clocks, one far away and one stationary near a black hole, accumulate time at different rates."></canvas><div class="experiment-badge"><i></i> TWO CLOCKS / ONE UNIVERSE</div><span class="experiment-hint">THE NEAR CLOCK RUNS SLOWER RELATIVE TO INFINITY</span></div><div class="experiment-console"><span class="eyebrow">EXPERIMENT / 02</span><h3>Your minute.<br>Someone else’s hour.</h3><p>Bring a stationary clock closer to the horizon. Compare its elapsed time with an ideal clock infinitely far away.</p><label>Distance from center <output id="clock-radius-label"></output><input id="clock-radius" type="range" min="1.01" max="20" step=".01" value="1.5"></label><div class="experiment-presets"><button data-clock-radius="1.01">1.01 Rs</button><button data-clock-radius="1.5">1.5 Rs</button><button data-clock-radius="10">10 Rs</button></div><div class="clock-readouts"><div><span>FAR CLOCK</span><strong id="clock-far">0.00 s</strong></div><div><span>NEAR CLOCK</span><strong id="clock-near">0.00 s</strong></div></div><div class="experiment-result"><span>FOR EVERY MINUTE ON THE NEAR CLOCK</span><strong id="clock-ratio"></strong><small id="clock-redshift"></small></div><div class="experiment-presets"><button id="clock-pause" aria-pressed="false">Pause clocks</button><button id="clock-reset">Reset clocks ↺</button></div><p class="experiment-note">dτ/dt = √(1 − Rs/r) for a stationary, hovering clock outside a nonrotating black hole. Includes gravitational time dilation only; orbiting or falling clocks also depend on motion. Hovering near the horizon requires extreme acceleration.</p></div></div>
 <div id="panel-tides" role="tabpanel" aria-labelledby="tab-tides" class="relativity-panel" hidden><div class="experiment-visual"><canvas id="tides-canvas" role="img" aria-label="Schematic radial stretching of a two-meter object by the black hole's tidal gradient."></canvas><div class="experiment-badge"><i></i> THE DIFFERENCE THAT PULLS YOU APART</div><span class="experiment-hint">DEFORMATION IS EXAGGERATED / OBJECT SIZE IS NOT TO SCALE</span></div><div class="experiment-console"><span class="eyebrow">EXPERIMENT / 03</span><h3>Bigger black hole.<br>Gentler horizon?</h3><p>At the same number of horizon radii, a more massive black hole has a smaller tidal gradient. Change the mass to test this counterintuitive result.</p><label>Distance / horizon radii <output id="tidal-radius-label"></output><input id="tidal-radius" type="range" min="1.05" max="20" step=".05" value="3"></label><label>Black-hole mass<select id="tidal-mass"><option value="10">Stellar / 10 M☉</option><option value="4300000">Sagittarius A* / 4.3 million M☉</option><option value="6500000000">M87* / 6.5 billion M☉</option></select></label><div class="experiment-result" aria-live="polite"><span>ACCELERATION DIFFERENCE ACROSS 2 METERS</span><strong id="tidal-value"></strong><small id="tidal-detail"></small></div><div class="tidal-scale"><span>GENTLER</span><i><b id="tidal-meter"></b></i><span>STRONGER</span></div><p class="experiment-note">Leading radial tidal difference Δa ≈ 2GM L/r³ with L = 2 m, using the selected mass and radius. The particle figure illustrates the gradient; it is not a material, injury, or survival simulation. Distances are measured from the center.</p></div></div>
 <div class="relativity-foot"><span>Rs = 2GM/c² / ALL EXPERIMENTS USE A NONROTATING BLACK HOLE</span><button id="bh-share">Share this experiment ↗</button><a href="https://science.nasa.gov/universe/black-holes/anatomy/" target="_blank" rel="noopener">Science reference ↗</a></div><input id="bh-share-url" aria-label="Experiment share link" readonly hidden>`;
 let active='photon', visible=false,last=0,time=0,far=0,near=0,clockPaused=false,progress=1,flight=false,path,bundle=[],dirty=true;
 const photonTools=setupPhotonTools(root,{getPath:()=>path,getImpact:()=>+$('#photon-impact').value,getProgress:()=>progress,setProgress:p=>{progress=p;flight=false;dirty=true},toggleFlight:()=>{flight=!flight;dirty=true},dirty:()=>dirty=true});
 const canvases=['photon','clock','tides'].map(id=>$('#'+id+'-canvas'));
 function resize(){for(const canvas of canvases){const rect=canvas.getBoundingClientRect();if(!rect.width)continue;const ratio=Math.min(devicePixelRatio,1.5);canvas.width=rect.width*ratio;canvas.height=rect.height*ratio;}dirty=true;}
 new ResizeObserver(resize).observe(root);new IntersectionObserver(e=>{visible=e[0].isIntersecting;dirty=true;}).observe(root);
 function select(name){active=name;root.querySelectorAll('[data-relativity]').forEach(b=>{const on=b.dataset.relativity===name;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;$('#panel-'+b.dataset.relativity).hidden=!on;});resize();dirty=true;}
 root.querySelectorAll('[data-relativity]').forEach((b,i,buttons)=>{b.onclick=()=>select(b.dataset.relativity);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const j=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;select(buttons[j].dataset.relativity);buttons[j].focus();};});
 function photon(){const b=+$('#photon-impact').value;path=tracePhoton(b);bundle=[tracePhoton(Math.max(1.5,b-.045)),tracePhoton(b+.045)];$('#photon-impact-label').textContent=b.toFixed(3)+' Rs';$('#photon-outcome').textContent=path.outcome==='captured'?'Captured.':path.outcome==='escaped'?'Escaped.':'Still near the edge.';$('#photon-detail').textContent=`Closest sampled approach: ${path.minRadius.toFixed(3)} Rs · critical b ≈ ${CRITICAL_IMPACT.toFixed(3)} Rs`;progress=1;flight=false;photonTools.rebuild();dirty=true;}
 $('#photon-impact').oninput=photon;root.querySelectorAll('[data-impact]').forEach(b=>b.onclick=()=>{$('#photon-impact').value=b.dataset.impact;photon();});$('#photon-bundle').onchange=()=>dirty=true;$('#photon-replay').onclick=()=>{progress=0;flight=true;dirty=true;};
 let aim=false;const aimCanvas=$('#photon-canvas');function aimAt(e){const r=aimCanvas.getBoundingClientRect(),b=1.5+4*(1-(e.clientY-r.top)/r.height);$('#photon-impact').value=Math.max(1.5,Math.min(5.5,b));photon();}aimCanvas.onpointerdown=e=>{aim=true;aimCanvas.setPointerCapture(e.pointerId);aimAt(e);};aimCanvas.onpointermove=e=>{if(aim)aimAt(e);};['pointerup','pointercancel','lostpointercapture'].forEach(type=>aimCanvas.addEventListener(type,()=>aim=false));
 function clocks(){const r=+$('#clock-radius').value,rate=clockRate(r);$('#clock-radius-label').textContent=r.toFixed(2)+' Rs';$('#clock-ratio').textContent=(60/rate).toFixed(1)+' seconds far away';$('#clock-redshift').textContent=`Near-clock rate: ${(rate*100).toFixed(2)}% · gravitational redshift z = ${(1/rate-1).toFixed(3)}`;far=near=0;dirty=true;}
 $('#clock-radius').oninput=clocks;root.querySelectorAll('[data-clock-radius]').forEach(b=>b.onclick=()=>{$('#clock-radius').value=b.dataset.clockRadius;clocks();});$('#clock-pause').onclick=e=>{clockPaused=!clockPaused;e.currentTarget.setAttribute('aria-pressed',clockPaused);e.currentTarget.textContent=clockPaused?'Resume clocks':'Pause clocks';};$('#clock-reset').onclick=()=>{far=near=0;dirty=true;};
 function tides(){const mass=+$('#tidal-mass').value,r=+$('#tidal-radius').value,a=tidalGradient(mass,r);$('#tidal-radius-label').textContent=r.toFixed(2)+' Rs';$('#tidal-value').textContent=a>=1000?a.toExponential(3)+' m/s²':a<.001?a.toExponential(3)+' m/s²':a.toFixed(4)+' m/s²';$('#tidal-detail').textContent=`${(a/9.80665).toExponential(2)} × Earth's surface gravity · radius ${blackholeReference(mass).rs.toLocaleString('en-US',{maximumFractionDigits:1})} km × ${r.toFixed(2)}`;$('#tidal-meter').style.width=Math.max(2,Math.min(100,(Math.log10(a)+10)/18*100))+'%';dirty=true;}
 $('#tidal-radius').oninput=tides;$('#tidal-mass').onchange=tides;
 $('#bh-share').onclick=async()=>{const url=new URL(location.href);url.hash='relativity-lab';url.searchParams.set('lab',active);if(active==='photon'){url.searchParams.set('impact',$('#photon-impact').value);for(const [key,id] of [['rays','photon-mode'],['spread','photon-spread'],['wavelength','photon-wavelength'],['rate','photon-rate']])url.searchParams.set(key,$('#'+id).value);}if(active==='clock')url.searchParams.set('radius',$('#clock-radius').value);if(active==='tides'){url.searchParams.set('radius',$('#tidal-radius').value);url.searchParams.set('tidalMass',$('#tidal-mass').value);}const input=$('#bh-share-url');input.value=url.href;input.hidden=false;try{await navigator.clipboard.writeText(url.href);$('#bh-share').textContent='Link copied ✓';}catch{input.focus();input.select();$('#bh-share').textContent='Copy the link below';}};
 const params=new URLSearchParams(location.search),validRange=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b;
 if(validRange(+params.get('impact'),1.5,5.5))$('#photon-impact').value=params.get('impact');
 if(params.get('lab')==='clock'&&validRange(+params.get('radius'),1.01,20))$('#clock-radius').value=params.get('radius');
 if(params.get('lab')==='tides'){if(validRange(+params.get('radius'),1.05,20))$('#tidal-radius').value=params.get('radius');if(['10','4300000','6500000000'].includes(params.get('tidalMass')))$('#tidal-mass').value=params.get('tidalMass');}
 if(['single','fan','beam'].includes(params.get('rays')))$('#photon-mode').value=params.get('rays');if(validRange(+params.get('spread'),.01,1.2))$('#photon-spread').value=params.get('spread');if(validRange(+params.get('wavelength'),380,750))$('#photon-wavelength').value=params.get('wavelength');if(['.25','1','2','4'].includes(params.get('rate')))$('#photon-rate').value=params.get('rate');photon();clocks();tides();select(['photon','clock','tides'].includes(params.get('lab'))?params.get('lab'):'photon');
 function base(canvas){const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.clearRect(0,0,w,h);c.fillStyle='#080c10';c.fillRect(0,0,w,h);c.strokeStyle='#1a242b';c.lineWidth=1;for(let x=0;x<w;x+=w/16){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}for(let y=0;y<h;y+=h/10){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();}return {c,w,h};}
 function hole(c,x,y,r){const g=c.createRadialGradient(x,y,r*.8,x,y,r*2.7);g.addColorStop(0,'#000');g.addColorStop(.37,'#d8a66a65');g.addColorStop(.46,'#bd733e18');g.addColorStop(1,'#0000');c.fillStyle=g;c.beginPath();c.arc(x,y,r*2.7,0,Math.PI*2);c.fill();c.fillStyle='#010203';c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();c.strokeStyle='#d2b17a';c.lineWidth=1;c.stroke();}
 function drawPhoton(){const {c,w,h}=base(aimCanvas),scale=Math.min(w/25,h/14),cx=w*.51,cy=h*.55;if(!photonTools.grid){c.fillStyle='#080c10';c.fillRect(0,0,w,h);}photonTools.draw(c,{cx,cy,scale,progress,w,h});hole(c,cx,cy,scale);c.setLineDash([4,5]);c.strokeStyle='#b795623d';c.beginPath();c.arc(cx,cy,scale*1.5,0,Math.PI*2);c.stroke();c.setLineDash([]);function line(trace,color,fraction=1){c.strokeStyle=color;c.lineWidth=1.7;const count=Math.max(2,Math.floor(trace.points.length*fraction));c.beginPath();trace.points.slice(0,count).forEach(([x,y],i)=>i?c.lineTo(cx+x*scale,cy-y*scale):c.moveTo(cx+x*scale,cy-y*scale));c.stroke();return trace.points[Math.min(count-1,trace.points.length-1)];}if($('#photon-bundle').checked)bundle.forEach((p,i)=>line(p,i?'#85afc070':'#d4b37b70'));const p=line(path,photonTools.color(),progress);if(p){const x=cx+p[0]*scale,y=cy-p[1]*scale;const g=c.createRadialGradient(x,y,0,x,y,12);g.addColorStop(0,'#fff3d5');g.addColorStop(1,'#e1a86700');c.fillStyle=g;c.beginPath();c.arc(x,y,12,0,Math.PI*2);c.fill();}c.font=`${Math.max(10,w*.013)}px monospace`;c.fillStyle='#9faeb6';c.fillText('1.0 Rs / EVENT HORIZON',cx+scale*1.25,cy+scale*.35);c.fillText('1.5 Rs / PHOTON SPHERE',cx+scale*1.9,cy+scale*1.85);}
 function drawClock(){const {c,w,h}=base($('#clock-canvas')),rad=Math.min(w*.17,h*.25);function clock(x,y,seconds,color,label){c.strokeStyle='#27333b';c.lineWidth=1;c.beginPath();c.arc(x,y,rad,0,Math.PI*2);c.stroke();for(let i=0;i<60;i++){const a=i/60*Math.PI*2;c.beginPath();c.moveTo(x+Math.sin(a)*rad*.94,y-Math.cos(a)*rad*.94);c.lineTo(x+Math.sin(a)*rad*(i%5?.90:.84),y-Math.cos(a)*rad*(i%5?.90:.84));c.stroke();}const a=seconds/60*Math.PI*2;c.strokeStyle=color;c.lineWidth=2.5;c.beginPath();c.moveTo(x,y);c.lineTo(x+Math.sin(a)*rad*.76,y-Math.cos(a)*rad*.76);c.stroke();c.fillStyle=color;c.beginPath();c.arc(x,y,4,0,Math.PI*2);c.fill();c.font=`${Math.max(11,w*.017)}px monospace`;c.textAlign='center';c.fillText(seconds.toFixed(1)+' s',x,y+rad*.48);c.font=`${Math.max(9,w*.012)}px monospace`;c.fillStyle='#9aabb5';c.fillText(label,x,y+rad+35);}clock(w*.27,h*.48,near,'#f4c083','NEAR THE HORIZON');clock(w*.73,h*.48,far,'#9dc9df','INFINITELY FAR AWAY');c.textAlign='left';$('#clock-far').textContent=far.toFixed(2)+' s';$('#clock-near').textContent=near.toFixed(2)+' s';}
 function drawTides(){const {c,w,h}=base($('#tides-canvas')),mass=+$('#tidal-mass').value,r=+$('#tidal-radius').value,a=tidalGradient(mass,r),stretch=1+Math.max(0,Math.min(3,(Math.log10(a)+2)/3)),cx=w*.64,cy=h*.52;hole(c,w*.22,cy,Math.min(w*.095,h*.16));for(let i=0;i<190;i++){const t=i*2.399963,rr=Math.sqrt(i/190),x=Math.cos(t)*rr,y=Math.sin(t)*rr,p=Math.sin(time*.7+i*.1)*.04;c.fillStyle=i%4?'#a0cadd':'#f6cc95';c.globalAlpha=.5+(i%5)*.1;c.beginPath();c.arc(cx+(x+p)*w*.055*stretch,cy+y*h*.19/Math.sqrt(stretch),1.7,0,Math.PI*2);c.fill();}c.globalAlpha=1;c.strokeStyle='#e6bb7470';for(const dir of [-1,1]){const x=cx+dir*w*.11*stretch;c.beginPath();c.moveTo(cx+dir*w*.05,cy);c.lineTo(x,cy);c.lineTo(x-dir*8,cy-5);c.moveTo(x,cy);c.lineTo(x-dir*8,cy+5);c.stroke();}c.fillStyle='#8fa3af';c.font=`${Math.max(10,w*.013)}px monospace`;c.fillText('RADIAL STRETCH / TRANSVERSE SQUEEZE',w*.37,h*.84);}
 function frame(now){requestAnimationFrame(frame);const dt=Math.min(.06,(now-last)/1000)||0;last=now;if(!visible||document.hidden)return;const moving=api.getState().motion;if(moving){time+=dt;if(active==='clock'&&!clockPaused){far+=dt;near+=dt*clockRate(+$('#clock-radius').value);}if(active==='photon'&&flight){progress=Math.min(1,progress+dt*.25*photonTools.speed);if(progress===1)flight=false;}}if(!dirty&&!moving)return;if(active==='photon')drawPhoton();if(active==='clock')drawClock();if(active==='tides')drawTides();dirty=false;}
 requestAnimationFrame(frame);
}
